/** MolCrafts Fluent 2 scaffold. Products may rebind semantic brand/surface slots. */
@import "./fluent-theme.css";
@import "./constitution-base.css";
@import "./constitution-theme.css";

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-surface: var(--surface);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-subtle-foreground: var(--subtle-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-input-bottom: var(--input-bottom);
  --color-input-hover: var(--input-hover);
  --color-neutral: var(--neutral);
  --color-neutral-foreground: var(--neutral-foreground);
  --color-primary-hover: var(--primary-hover);
  --color-primary-pressed: var(--primary-pressed);
  --color-primary-muted: var(--primary-muted);
  --color-primary-muted-foreground: var(--primary-muted-foreground);
  --color-primary-link: var(--primary-link);
  --color-primary-link-hover: var(--primary-link-hover);
  --color-secondary: var(--secondary);
  --color-secondary-hover: var(--secondary-hover);
  --color-secondary-pressed: var(--secondary-pressed);
  --color-secondary-muted: var(--secondary-muted);
  --color-secondary-muted-foreground: var(--secondary-muted-foreground);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-interactive: var(--interactive);
  --color-interactive-pressed: var(--interactive-pressed);
  --color-interactive-foreground: var(--interactive-foreground);
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-accent-pressed: var(--accent-pressed);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent-muted: var(--accent-muted);
  --color-accent-muted-foreground: var(--accent-muted-foreground);
  --color-link: var(--link);
  --color-link-hover: var(--link-hover);
  --color-ring: var(--ring);
  --color-focus-inner: var(--focus-inner);
  --color-disabled-background: var(--disabled-background);
  --color-disabled-foreground: var(--disabled-foreground);
  --color-disabled-border: var(--disabled-border);
  --color-tooltip-background: var(--tooltip-background);
  --color-tooltip-foreground: var(--tooltip-foreground);
  --color-overlay-scrim: var(--overlay-scrim);
  --color-status-draft: var(--status-draft);
  --color-status-ready: var(--status-ready);
  --color-status-queued: var(--status-queued);
  --color-status-running: var(--status-running);
  --color-status-completed: var(--status-completed);
  --color-status-failed: var(--status-failed);
  --color-status-failed-hover: var(--status-failed-hover);
  --color-status-cancelled: var(--status-cancelled);
  --color-status-cached: var(--status-cached);
  --color-status-warning: var(--status-warning);
  --color-status-ready-foreground: var(--status-ready-foreground);
  --color-status-running-foreground: var(--status-running-foreground);
  --color-status-completed-foreground: var(--status-completed-foreground);
  --color-status-failed-foreground: var(--status-failed-foreground);
  --color-status-warning-foreground: var(--status-warning-foreground);
  --color-status-running-soft: var(--status-running-soft);
  --color-status-completed-soft: var(--status-completed-soft);
  --color-status-failed-soft: var(--status-failed-soft);
  --color-status-warning-soft: var(--status-warning-soft);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-success-soft: var(--success-soft);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-warning-soft: var(--warning-soft);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
  --color-info-soft: var(--info-soft);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --shadow-card: var(--elevation-card);
  --shadow-popup: var(--elevation-popup);
  --shadow-overlay: var(--elevation-dialog);
  --animate-accordion-down: mol-accordion-down var(--motion-base) var(--motion-enter);
  --animate-accordion-up: mol-accordion-up var(--motion-fast) var(--motion-exit);
}

/** Generated from @fluentui/react-theme 9.2.2. Run npm run build:tokens. */

:where(:root, :host) {
  color-scheme: light;
  --background: #fafafa;
  --foreground: #242424;
  --surface: #ffffff;
  --card: #ffffff;
  --card-foreground: #242424;
  --popover: #ffffff;
  --popover-foreground: #242424;
  --muted: #f5f5f5;
  --muted-foreground: #424242;
  --subtle-foreground: #616161;
  --border: #e0e0e0;
  --input: #d1d1d1;
  --input-bottom: #616161;
  --input-hover: #c7c7c7;
  --neutral: #ffffff;
  --neutral-foreground: #242424;
  --interactive: #f5f5f5;
  --interactive-pressed: #e0e0e0;
  --interactive-foreground: #242424;
  --primary: #0f6cbd;
  --primary-hover: #115ea3;
  --primary-pressed: #0c3b5e;
  --primary-foreground: #ffffff;
  --primary-muted: #ebf3fc;
  --primary-muted-foreground: #115ea3;
  --primary-link: #115ea3;
  --primary-link-hover: #0f548c;
  --secondary: #5c2e91;
  --secondary-muted: #c6b1de;
  --secondary-muted-foreground: #341a51;
  --ring: #000000;
  --focus-inner: #ffffff;
  --disabled-background: #f0f0f0;
  --disabled-foreground: #bdbdbd;
  --disabled-border: #e0e0e0;
  --tooltip-background: #292929;
  --tooltip-foreground: #ffffff;
  --overlay-scrim: rgba(0, 0, 0, 0.4);
  --secondary-foreground: #ffffff;
  --secondary-hover: color-mix(in srgb, var(--secondary), black 10%);
  --secondary-pressed: color-mix(in srgb, var(--secondary), black 20%);
}

.dark, :where(:root, :host).dark {
  color-scheme: dark;
  --background: #1f1f1f;
  --foreground: #ffffff;
  --surface: #292929;
  --card: #292929;
  --card-foreground: #ffffff;
  --popover: #292929;
  --popover-foreground: #ffffff;
  --muted: #141414;
  --muted-foreground: #d6d6d6;
  --subtle-foreground: #adadad;
  --border: #525252;
  --input: #666666;
  --input-bottom: #adadad;
  --input-hover: #757575;
  --neutral: #292929;
  --neutral-foreground: #ffffff;
  --interactive: #3d3d3d;
  --interactive-pressed: #1f1f1f;
  --interactive-foreground: #ffffff;
  --primary: #115ea3;
  --primary-hover: #0f6cbd;
  --primary-pressed: #0c3b5e;
  --primary-foreground: #ffffff;
  --primary-muted: #082338;
  --primary-muted-foreground: #62abf5;
  --primary-link: #479ef5;
  --primary-link-hover: #62abf5;
  --secondary: #9470bd;
  --secondary-muted: #341a51;
  --secondary-muted-foreground: #c6b1de;
  --ring: #ffffff;
  --focus-inner: #000000;
  --disabled-background: #141414;
  --disabled-foreground: #5c5c5c;
  --disabled-border: #424242;
  --tooltip-background: #ffffff;
  --tooltip-foreground: #242424;
  --overlay-scrim: rgba(0, 0, 0, 0.5);
  --secondary-foreground: #000000;
  --secondary-hover: color-mix(in srgb, var(--secondary), white 10%);
  --secondary-pressed: color-mix(in srgb, var(--secondary), white 20%);
}

/* Rebind legacy accent slots at each product scope so nested palettes also work. */
:where(:root, :host), .mol-product-theme {
  --accent: var(--primary);
  --accent-hover: var(--primary-hover);
  --accent-pressed: var(--primary-pressed);
  --accent-foreground: var(--primary-foreground);
  --accent-muted: var(--primary-muted);
  --accent-muted-foreground: var(--primary-muted-foreground);
  --link: var(--primary-link);
  --link-hover: var(--primary-link-hover);
}

/** Generated from @fluentui/react-theme 9.2.2. Run npm run build:tokens. */

:where(:root, :host) {
  --motion-fast: 100ms;
  --motion-base: 150ms;
  --motion-slow: 200ms;
  --motion-ease: cubic-bezier(0.33,0,0.67,1);
  --motion-enter: cubic-bezier(0,0,0,1);
  --motion-exit: cubic-bezier(1,0,1,1);
  --neutral-shadow-ambient: rgba(0,0,0,0.12);
  --neutral-shadow-key: rgba(0,0,0,0.14);
  --status-draft: #616161;
  --status-ready: #424242;
  --status-queued: #004377;
  --status-running: #0078d4;
  --status-completed: #107c10;
  --status-failed: #d13438;
  --status-failed-hover: #bc2f32;
  --status-cancelled: #616161;
  --status-cached: #341a51;
  --status-warning: #fde300;
  --status-ready-foreground: #424242;
  --status-running-foreground: #004377;
  --status-completed-foreground: #0e700e;
  --status-failed-foreground: #bc2f32;
  --status-warning-foreground: #817400;
}

.dark, :where(:root, :host).dark {
  --neutral-shadow-ambient: rgba(0,0,0,0.24);
  --neutral-shadow-key: rgba(0,0,0,0.28);
  --status-draft: #adadad;
  --status-ready: #d6d6d6;
  --status-queued: #a9d3f2;
  --status-running: #5caae5;
  --status-cancelled: #adadad;
  --status-cached: #c6b1de;
  --status-ready-foreground: #d6d6d6;
  --status-running-foreground: #a9d3f2;
  --status-completed-foreground: #54b054;
  --status-failed-foreground: #e37d80;
  --status-warning-foreground: #feee66;
}

/** Shared Fluent 2 behavior and status roles. No product brand overrides. */
@import "./fluent-foundation.css";

:where(:root, :host) {
  --constitution-surface: var(--card, var(--background, #ffffff));
  --motion-progress-spin: 850ms;
  --motion-progress-pulse: 1200ms;
  --default-transition-duration: var(--motion-base);
  --default-transition-timing-function: var(--motion-ease);
  --ease-standard: var(--motion-ease);
  --status-running-soft: color-mix(in srgb, var(--status-running) 12%, var(--constitution-surface));
  --status-completed-soft: color-mix(in srgb, var(--status-completed) 12%, var(--constitution-surface));
  --status-failed-soft: color-mix(in srgb, var(--status-failed) 10%, var(--constitution-surface));
  --status-warning-soft: color-mix(in srgb, var(--status-warning) 14%, var(--constitution-surface));
  --destructive: var(--status-failed);
  --destructive-foreground: #ffffff;
  --success: var(--status-completed);
  --success-foreground: var(--status-completed-foreground);
  --success-soft: var(--status-completed-soft);
  --warning: var(--status-warning);
  --warning-foreground: var(--status-warning-foreground);
  --warning-soft: var(--status-warning-soft);
  --info: var(--status-running);
  --info-foreground: var(--status-running-foreground);
  --info-soft: var(--status-running-soft);
  --elevation-card: 0 0 2px var(--neutral-shadow-ambient), 0 2px 4px var(--neutral-shadow-key);
  --elevation-popup: 0 0 2px var(--neutral-shadow-ambient), 0 4px 8px var(--neutral-shadow-key);
  --elevation-dialog: 0 0 8px var(--neutral-shadow-ambient), 0 32px 64px var(--neutral-shadow-key);
}

/* Two-color keyboard focus remains legible on neutral and brand surfaces. */
.mol-focus:focus-visible {
  outline: 2px solid var(--ring, currentColor);
  outline-offset: 2px;
  box-shadow: 0 0 0 2px var(--focus-inner, var(--background, #ffffff));
}

@keyframes mol-progress-spin { to { transform: rotate(360deg); } }
@keyframes mol-progress-pulse { 50% { opacity: 0.5; } }
.mol-motion-progress-pulse { animation: mol-progress-pulse var(--motion-progress-pulse) var(--motion-ease) infinite; }
@keyframes mol-fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes mol-fade-out { from { opacity: 1; } to { opacity: 0; } }
@keyframes mol-popup-in { from { opacity: 0; scale: 0.98; } to { opacity: 1; scale: 1; } }
@keyframes mol-popup-out { from { opacity: 1; scale: 1; } to { opacity: 0; scale: 0.98; } }
@keyframes mol-accordion-down { from { height: 0; } to { height: var(--radix-accordion-content-height); } }
@keyframes mol-accordion-up { from { height: var(--radix-accordion-content-height); } to { height: 0; } }

.mol-motion-overlay[data-state="open"] { animation: mol-fade-in var(--motion-base) var(--motion-enter); }
.mol-motion-overlay[data-state="closed"] { animation: mol-fade-out var(--motion-fast) var(--motion-exit); }
.mol-motion-popup[data-state="open"],
.mol-motion-popup[data-state="delayed-open"],
.mol-motion-popup[data-state="instant-open"],
.mol-motion-dialog[data-state="open"] { animation: mol-popup-in var(--motion-base) var(--motion-enter); }
.mol-motion-popup[data-state="closed"],
.mol-motion-dialog[data-state="closed"] { animation: mol-popup-out var(--motion-fast) var(--motion-exit); }
.mol-motion-sheet[data-state="open"] { animation: mol-fade-in var(--motion-slow) var(--motion-enter); }
.mol-motion-sheet[data-state="closed"] { animation: mol-fade-out var(--motion-fast) var(--motion-exit); }

.mol-progress-spinner {
  display: inline-block;
  border-radius: 9999px;
  border-style: solid;
  border-color: color-mix(in srgb, var(--status-running) 28%, transparent);
  border-top-color: var(--status-running);
  animation: mol-progress-spin var(--motion-progress-spin) linear infinite;
}
.mol-progress-spinner-sm { width: 0.875rem; height: 0.875rem; border-width: 2px; }
.mol-progress-spinner-md { width: 1.25rem; height: 1.25rem; border-width: 2.5px; }

@media (prefers-reduced-motion: reduce) {
  :where(:root, :host) {
    --motion-fast: 0ms;
    --motion-base: 0ms;
    --motion-slow: 0ms;
  }
  .mol-motion-overlay, .mol-motion-popup, .mol-motion-dialog, .mol-motion-sheet,
  [data-slot="accordion-content"] { animation: none !important; }
  .mol-progress-spinner, .mol-motion-progress-pulse { animation: none; }
}

@media (forced-colors: active) {
  .mol-focus:focus-visible { outline-color: Highlight; box-shadow: none; }
  [data-slot="button"], [data-slot="input"], [data-slot="textarea"],
  [data-slot="select-trigger"], [data-slot="checkbox"], [data-slot="switch"] { border: 1px solid ButtonText; }
  [data-slot="checkbox"][data-state="checked"],
  [data-slot="switch"][data-state="checked"] { background: Highlight; color: HighlightText; }
}

/** Generated from @fluentui/react-theme 9.2.2. Run npm run build:tokens. */
/* Shared geometry only. Product brand mappings belong to the product theme. */
@theme inline {
  --font-sans: 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, BlinkMacSystemFont, Roboto, 'Helvetica Neue', sans-serif;
  --font-mono: Consolas, 'Courier New', Courier, monospace;
  --text-micro: 10px;
  --text-micro--line-height: 14px;
  --text-label: 12px;
  --text-label--line-height: 16px;
  --text-body: 14px;
  --text-body--line-height: 20px;
  --text-body-lg: 16px;
  --text-body-lg--line-height: 22px;
  --text-title: 20px;
  --text-title--line-height: 28px;
  --text-heading: 24px;
  --text-heading--line-height: 32px;
  --text-display: 32px;
  --text-display--line-height: 40px;
  --radius-control: 4px;
  --radius-panel: 8px;
  --radius-overlay: 8px;
  --radius-checkbox: 2px;
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 8px;
  --spacing-control-compact: 1.75rem;
  --spacing-control: 2rem;
  --spacing-control-comfortable: 2.5rem;
  --spacing-toolbar-compact: 2.5rem;
  --spacing-toolbar: 2.75rem;
  --spacing-statusbar: 1.75rem;
  --spacing-touch-target: 2.75rem;
  --spacing-menu: 8rem;
  --spacing-dialog-sm: 24rem;
  --spacing-dialog-md: 30rem;
  --spacing-dialog-lg: 34rem;
  --spacing-dialog-scroll: 80vh;
  --spacing-overlay-viewport: calc(100% - 2rem);
  --ease-standard: cubic-bezier(0.33,0,0.67,1);
}
